/**
 * Offline support for production builds (worker generated by scripts/build-sw.mjs).
 *
 * The worker precaches only the application shell. The art this page's boot
 * actually downloaded is listed from Resource Timing and posted to the worker,
 * which caches it best-effort (during its first install, before it activates),
 * so an offline reload finds everything the boot needs without every player
 * downloading the whole art library.
 */
import { isRetryableArtImportError, isStaleArtImportError } from './game/import-retry';

/** Resource Timing drops entries past its buffer (250 by default); the boot loads more. */
export function recordBootResources() {
  try {
    performance.setResourceTimingBufferSize(4000);
  } catch {
    /* Older engines keep the default buffer. */
  }
}

function loadedPaths() {
  const paths = new Set<string>();
  for (const entry of performance.getEntriesByType('resource')) {
    try {
      const url = new URL(entry.name);
      if (url.origin === location.origin && !url.search) paths.add(url.pathname);
    } catch {
      /* Not a URL. */
    }
  }
  return [...paths];
}

/**
 * What offline play can rely on right now: 'unsupported' (no service worker, or a development
 * page), 'preparing' until the worker has stored this page's boot art, 'ready' once it has, or
 * 'partial' when some of that art could not be stored (a retry is offered).
 */
export type OfflineStatus = 'unsupported' | 'preparing' | 'ready' | 'partial';
let status: OfflineStatus = 'unsupported';
let onStatus: (status: OfflineStatus) => void = () => {};
export const offlineStatus = () => status;
/** The HUD redraws its Settings note when the status changes. */
export function watchOfflineStatus(listener: (status: OfflineStatus) => void) {
  onStatus = listener;
}
function setStatus(next: OfflineStatus) {
  status = next;
  document.documentElement.dataset.offline = next;
  onStatus(next);
}
/** Asks the active worker to store this page's art again (after a partial warm-up). */
export function retryOfflineWarm() {
  const worker = 'serviceWorker' in navigator ? navigator.serviceWorker.controller : null;
  if (!worker) return;
  setStatus('preparing');
  worker.postMessage({ type: 'warm', urls: loadedPaths() });
}

const idle = (callback: () => void) =>
  'requestIdleCallback' in window
    ? requestIdleCallback(callback, { timeout: 4000 })
    : setTimeout(callback, 1000);

/**
 * Registers the worker once the village is on screen and the browser is idle, so
 * the install never competes with the boot preload for bandwidth.
 */
export function registerOfflineSupport() {
  let updating = false;
  let reloadPending = false;
  const activateUpdate = (worker: ServiceWorker) => {
    reloadPending = true;
    // Another tab may already be activating this prompt's worker. There may
    // be no further controllerchange event to reload this document for us.
    if (
      worker.state === 'activating' ||
      worker.state === 'activated' ||
      worker.state === 'redundant'
    ) {
      window.location.reload();
      return;
    }
    try {
      worker.postMessage({ type: 'activate-update' });
      updating = true;
    } catch {
      window.location.reload();
    }
  };
  const reloadOntoRelease = async () => {
    if (reloadPending) return;
    reloadPending = true;
    try {
      const registration =
        'serviceWorker' in navigator ? await navigator.serviceWorker.getRegistration() : undefined;
      // A long-open page may hit a removed chunk before the browser checks for updates.
      // Share one deadline between discovering and finishing that replacement release.
      const deadline = performance.now() + 10000;
      if (registration && !registration.waiting && !registration.installing)
        await new Promise<void>((resolve) => {
          const done = () => {
            clearTimeout(timer);
            resolve();
          };
          const timer = setTimeout(done, 10000);
          registration.update().then(done, done);
        });
      const installing = registration?.installing;
      if (installing)
        await new Promise<void>((resolve) => {
          const done = () => {
            clearTimeout(timer);
            installing.removeEventListener('statechange', changed);
            resolve();
          };
          const changed = () => {
            // Another tab may already have activated the completed worker.
            if (installing.state !== 'installing' && installing.state !== 'parsed') done();
          };
          // A slow or failed update must not leave recovery waiting forever.
          const timer = setTimeout(done, Math.max(0, deadline - performance.now()));
          installing.addEventListener('statechange', changed);
          changed();
        });
      if (updating) return;
      if (registration?.waiting) {
        // Reloading under the old worker repeats its cached HTML and missing chunk URL.
        // Switch the completed release first; controllerchange performs the one reload.
        activateUpdate(registration.waiting);
        return;
      }
    } catch {
      // Without a usable registration, the host can still provide the current page.
    }
    window.location.reload();
  };
  // A lazy chunk that no longer exists on the host (a deploy landed while this page was open
  // and no worker served it from cache) is fatal to the page in every other way; reload onto
  // the new version. The unload path settles any battle and stores the village first.
  window.addEventListener('vite:preloadError', (event) => {
    const error = (event as Event & { payload?: unknown }).payload;
    if (isRetryableArtImportError(error)) return;
    // Managed stale imports still reject to their caller while navigation begins.
    if (!isStaleArtImportError(error)) event.preventDefault();
    void reloadOntoRelease();
  });
  if (!('serviceWorker' in navigator)) return;
  setStatus('preparing');
  const container = navigator.serviceWorker;
  const post = (worker: ServiceWorker | null | undefined) =>
    worker?.postMessage({ type: 'warm', urls: loadedPaths() });
  container.addEventListener('message', (event: MessageEvent) => {
    if (event.data?.type === 'warmed') setStatus(event.data.failed ? 'partial' : 'ready');
  });
  // Files fetched before this page came under the worker's control never passed
  // through it; list them again once it takes over. An update the player accepted
  // reloads the page onto the release its new worker serves.
  container.addEventListener('controllerchange', () => {
    if (updating) window.location.reload();
    else post(container.controller);
  });
  idle(() => {
    container
      .register('/sw.js')
      .then((registration) => {
        post(registration.installing ?? container.controller);
        // Pages stay on the release their worker serves; a newer one waits until offered.
        const offer = () => {
          const waiting = registration.waiting;
          if (!waiting || !container.controller) return;
          offerUpdate(() => {
            activateUpdate(waiting);
          });
        };
        offer();
        registration.addEventListener('updatefound', () => {
          const next = registration.installing;
          next?.addEventListener('statechange', () => {
            if (next.state === 'installed') offer();
          });
        });
      })
      .catch((error) => console.warn(error));
  });
}

/** A small prompt to reload onto a downloaded update; the village is saved on unload. */
function offerUpdate(accept: () => void) {
  if (document.getElementById('update-ready')) return;
  const prompt = document.createElement('button');
  prompt.id = 'update-ready';
  prompt.type = 'button';
  prompt.textContent = 'Update ready · Reload';
  // Do not start first-gesture village audio downloads while switching workers.
  prompt.addEventListener('pointerdown', (event) => event.stopPropagation());
  prompt.addEventListener('click', () => {
    prompt.disabled = true;
    accept();
  });
  document.body.append(prompt);
}
